fn sort_plugin_entries(entries: &mut [(&PluginMarketplaceEntry, &PluginSummary, String)]) {
    entries.sort_by(|left, right| {
        right
            .1
            .installed
            .cmp(&left.1.installed)
            .then_with(|| {
                left.2
                    .to_ascii_lowercase()
                    .cmp(&right.2.to_ascii_lowercase())
            })
            .then_with(|| left.2.cmp(&right.2))
            .then_with(|| left.1.name.cmp(&right.1.name))
            .then_with(|| left.1.id.cmp(&right.1.id))
    });
}

/// Given the base labels for the per-marketplace tabs, append `(K/N)`
/// disambiguating suffixes to any labels that appear more than once, where `K`
/// is the 1-based occurrence index and `N` the total number of tabs sharing
/// that label.
fn disambiguate_marketplace_labels(base_labels: &[String]) -> Vec<String> {
    let mut totals: HashMap<&str, usize> = HashMap::new();
    for label in base_labels {
        *totals.entry(label.as_str()).or_insert(0) += 1;
    }
    let mut seen: HashMap<&str, usize> = HashMap::new();
    base_labels
        .iter()
        .map(|label| {
            let total = totals.get(label.as_str()).copied().unwrap_or(1);
            if total <= 1 {
                label.clone()
            } else {
                let occurrence = seen.entry(label.as_str()).or_insert(0);
                *occurrence += 1;
                format!("{label} ({occurrence}/{total})")
            }
        })
        .collect()
}

